  evidence.corruptions=[];for(const corruption of ['schema','integrity','component_identity']){beforeDeadline(plan,30000);const created=await request({kind:'create',definition_ref:'B24-OUTCOME-01',mode:'research',operation_id:crypto.randomUUID()});expect(created.ok).toBe(true);const damaged=await page.evaluate(async({run,corruption})=>{const db=await new Promise((resolve,reject)=>{const open=indexedDB.open('fogbound-map-b-game-1');open.onerror=()=>reject(open.error);open.onsuccess=()=>resolve(open.result);});try{const state=await new Promise((resolve,reject)=>{const tx=db.transaction('runs','readonly'),get=tx.objectStore('runs').get(run);get.onsuccess=()=>resolve(get.result);get.onerror=()=>reject(get.error);});if(corruption==='schema')state.schema=99;if(corruption==='component_identity')state.hashes.capabilities='0'.repeat(64);const canonical=v=>Array.isArray(v)?v.map(canonical):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])])):v,{integrity,...body}=state;state.integrity=corruption==='integrity'?'0'.repeat(64):Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(canonical(body)))))).map(x=>x.toString(16).padStart(2,'0')).join('');await new Promise((resolve,reject)=>{const tx=db.transaction(['runs','snapshots'],'readwrite');tx.objectStore('runs').put(state);tx.objectStore('snapshots').put({key:run+':'+state.revision,run_id:run,state});tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error);});return state;}finally{db.close();}}, {run:created.view.run_id,corruption});const rejected=await request({kind:'takeover',run_id:created.view.run_id,operation_id:crypto.randomUUID()});expect(rejected).toMatchObject({ok:false,code:'INVALID_SAVE'});const retained=await ownedSnapshot(page,created.view.run_id);expect(retained.state).toEqual(damaged);expect(retained.snapshot).toEqual(damaged);evidence.corruptions.push({corruption,damaged,rejected,retained});checked('Owned native '+corruption+' fault refused without overwriting the original invalid package');await page.reload();await expect(page.getByLabel('演练任务')).toBeVisible();}const resumed=await request({kind:'takeover',run_id:initialOutcome.run_id,operation_id:crypto.randomUUID()});expect(resumed.ok).toBe(true);const original=await ownedRecords(page,initialOutcome.run_id);expect(original.state.schema).toBe(10);evidence.scope='Native old4-9 and owned invalid schema/hash/component identity; strict unit/capability definition loader cases are separate core evidence, not invented native fixture claims.';
