export async function fullPath(page,route,checkpoint,expect){
 const current=()=>publicView(page),commit=async name=>{const before=await current(),button=page.getByRole('button',{name,exact:true});await expect(button).toBeEnabled();await button.press('Enter');await expect.poll(async()=>(await current()).revision).toBeGreaterThan(before.revision);await expect(page.getByRole('alert')).toHaveCount(0);};
 const advance=async seconds=>{await page.getByLabel('推进到时刻（秒）').fill(String(seconds));await commit('推进到该时刻');expect((await current()).sim_time).toBe(seconds*1000);};
 const prepare=async()=>{await page.getByLabel('准备目的').fill('取得两处记录并返回交付');await commit('保存准备草案');await commit('提交准备申请');};
 const returning=async actor=>{await page.getByRole('button',{name:'安排'+actor+'返回交付',exact:true}).press('Enter');await commit('确认返回交付');};
 if(route==='B')await prepare();await commit('下达R前往A');await advance(32);await commit('下达A处记录');await advance(80);await commit('下达R前往B');await advance(86);
 const before=await current();await page.getByTestId('intelligence-source-R3').getByRole('button',{name:'请求核实这份原文',exact:true}).press('Enter');await expect.poll(async()=>(await current()).revision).toBeGreaterThan(before.revision);
 if(route==='A'){await advance(108);await prepare();await advance(170);}else await advance(146);
 await commit('下达W维修B');await advance(route==='A'?237:214);await returning('W');page=await checkpoint('W_return_issued',page);await commit('下达B处记录');
 await advance(route==='A'?240:217);page=await checkpoint('W_return_moving',page);
 await advance(route==='A'?285:262);await returning('R');page=await checkpoint('R_return_issued',page);
 await advance(route==='A'?300:277);page=await checkpoint('W_handover_partial_R_moving',page);
 await advance(route==='A'?342:319);await expect(page.getByTestId('outcome-verification')).toContainText('已核验 3 人');
 await advance(route==='A'?350:327);page=await checkpoint('W_verified_R_handover_partial',page);
 await advance(route==='A'?390:367);page=await checkpoint('R_verified_receipt_pending',page);
 await advance(route==='A'?391:368);return current();
}
